"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[34814],{46591(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>i,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"cursos/docker/modulos/docker-swarm/cuestionario","title":"Cuestionario M11 \u2014 Docker Swarm","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/11-docker-swarm/cuestionario.md","sourceDirName":"cursos/docker/modulos/11-docker-swarm","slug":"/cursos/docker/modulos/docker-swarm/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/docker-swarm/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/docker-swarm/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/docker-swarm/ejercicio"}}');var s=o(74848),n=o(28453);const i={sidebar_label:"Cuestionario"},t="Cuestionario M11 \u2014 Docker Swarm",c={},d=[{value:"1. [Investigar] \xbfC\xf3mo funciona exactamente el algoritmo Raft en Swarm? Describ\xed el proceso de elecci\xf3n de l\xedder, replicaci\xf3n de logs, y qu\xe9 ocurre durante una partici\xf3n de red (split-brain).",id:"1-investigar-c\xf3mo-funciona-exactamente-el-algoritmo-raft-en-swarm-describ\xed-el-proceso-de-elecci\xf3n-de-l\xedder-replicaci\xf3n-de-logs-y-qu\xe9-ocurre-durante-una-partici\xf3n-de-red-split-brain",level:3},{value:"2. [Investigar] \xbfQu\xe9 es SwarmKit y c\xf3mo se relaciona con Docker Swarm? \xbfQu\xe9 otros proyectos usan SwarmKit?",id:"2-investigar-qu\xe9-es-swarmkit-y-c\xf3mo-se-relaciona-con-docker-swarm-qu\xe9-otros-proyectos-usan-swarmkit",level:3},{value:"3. [Investigar] \xbfC\xf3mo funciona exactamente el gossip protocol (SWIM) en Swarm y qu\xe9 informaci\xf3n se comparte? \xbfPor qu\xe9 es &quot;eventualmente consistente&quot; y no &quot;fuertemente consistente&quot; como Raft?",id:"3-investigar-c\xf3mo-funciona-exactamente-el-gossip-protocol-swim-en-swarm-y-qu\xe9-informaci\xf3n-se-comparte-por-qu\xe9-es-eventualmente-consistente-y-no-fuertemente-consistente-como-raft",level:3},{value:"4. [Investigar] \xbfC\xf3mo se compara Docker Swarm con HashiCorp Nomad como orquestador simple? \xbfEn qu\xe9 casos Nomad es preferible a Swarm?",id:"4-investigar-c\xf3mo-se-compara-docker-swarm-con-hashicorp-nomad-como-orquestador-simple-en-qu\xe9-casos-nomad-es-preferible-a-swarm",level:3},{value:"5. [Conectar] La clase menciona el puerto 2377 para comunicaci\xf3n manager-worker. \xbfQu\xe9 otros puertos usa Swarm y qu\xe9 protocolos? \xbfPor qu\xe9 la seguridad de red es cr\xedtica en un cluster Swarm?",id:"5-conectar-la-clase-menciona-el-puerto-2377-para-comunicaci\xf3n-manager-worker-qu\xe9-otros-puertos-usa-swarm-y-qu\xe9-protocolos-por-qu\xe9-la-seguridad-de-red-es-cr\xedtica-en-un-cluster-swarm",level:3},{value:"6. [Conectar] \xbfC\xf3mo funciona exactamente el scheduler de SwarmKit y qu\xe9 estrategias de placement ofrece? \xbfC\xf3mo se relaciona con los constraints y preferences de la clase?",id:"6-conectar-c\xf3mo-funciona-exactamente-el-scheduler-de-swarmkit-y-qu\xe9-estrategias-de-placement-ofrece-c\xf3mo-se-relaciona-con-los-constraints-y-preferences-de-la-clase",level:3},{value:"7. [Conectar] \xbfQu\xe9 es el &quot;Raft log compactation&quot; y por qu\xe9 es cr\xedtico para la salud a largo plazo de un cluster Swarm? \xbfQu\xe9 pasa si el log crece sin control?",id:"7-conectar-qu\xe9-es-el-raft-log-compactation-y-por-qu\xe9-es-cr\xedtico-para-la-salud-a-largo-plazo-de-un-cluster-swarm-qu\xe9-pasa-si-el-log-crece-sin-control",level:3},{value:"8. [Cuestionar] Docker Swarm vs Kubernetes para startups: \xbfEs Swarm suficiente o es una decisi\xf3n que limita el crecimiento futuro?",id:"8-cuestionar-docker-swarm-vs-kubernetes-para-startups-es-swarm-suficiente-o-es-una-decisi\xf3n-que-limita-el-crecimiento-futuro",level:3},{value:"9. [Cuestionar] \xbfDocker Swarm est\xe1 muerto? Evalu\xe1 su estado actual (2025) y si Docker Inc. sigue invirtiendo en \xe9l.",id:"9-cuestionar-docker-swarm-est\xe1-muerto-evalu\xe1-su-estado-actual-2025-y-si-docker-inc-sigue-invirtiendo-en-\xe9l",level:3},{value:"10. [Cuestionar] \xbfEs el Raft consensus de Swarm un cuello de botella? \xbfQu\xe9 implicaciones de rendimiento tiene que todas las operaciones de escritura pasen por el l\xedder?",id:"10-cuestionar-es-el-raft-consensus-de-swarm-un-cuello-de-botella-qu\xe9-implicaciones-de-rendimiento-tiene-que-todas-las-operaciones-de-escritura-pasen-por-el-l\xedder",level:3}];function l(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"cuestionario-m11--docker-swarm",children:"Cuestionario M11 \u2014 Docker Swarm"})}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,s.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"1-investigar-c\xf3mo-funciona-exactamente-el-algoritmo-raft-en-swarm-describ\xed-el-proceso-de-elecci\xf3n-de-l\xedder-replicaci\xf3n-de-logs-y-qu\xe9-ocurre-durante-una-partici\xf3n-de-red-split-brain",children:"1. [Investigar] \xbfC\xf3mo funciona exactamente el algoritmo Raft en Swarm? Describ\xed el proceso de elecci\xf3n de l\xedder, replicaci\xf3n de logs, y qu\xe9 ocurre durante una partici\xf3n de red (split-brain)."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Raft (Diego Ongaro, 2014) es un algoritmo de consenso donde un cluster de managers elige un l\xedder que recibe todas las escrituras y las replica a los followers. El proceso: 1) ",(0,s.jsx)(a.strong,{children:"Leader election"}),": cada manager tiene un timeout de elecci\xf3n aleatorio (150-300ms). Si un follower no recibe heartbeat del l\xedder dentro de ese timeout, se convierte en candidato, incrementa su t\xe9rmino, vota por s\xed mismo, y solicita votos de otros managers. Si recibe mayor\xeda, es el nuevo l\xedder. 2) ",(0,s.jsx)(a.strong,{children:"Log replication"}),": el l\xedder recibe un comando (ej. crear servicio), lo agrega a su log, y env\xeda AppendEntries a los followers. Cuando la mayor\xeda confirma, el l\xedder commitea la entrada y aplica el cambio. 3) ",(0,s.jsx)(a.strong,{children:"Split-brain"}),": si una partici\xf3n de red divide el cluster en dos grupos, solo el grupo con mayor\xeda (quorum) puede elegir l\xedder y continuar operando. El grupo minoritario no puede elegir l\xedder ni aceptar escrituras (se vuelve read-only). Cuando la partici\xf3n se resuelve, los nodos del grupo minoritario se reintegran y sus logs divergentes se sobrescriben con los del l\xedder."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La tesis doctoral de Diego Ongaro (Stanford, "In Search of an Understandable Consensus Algorithm") es la referencia can\xf3nica sobre Raft. Swarm implementa Raft usando la biblioteca etcd-io/raft (la misma que usa etcd). El Raft log de Swarm se almacena en ',(0,s.jsx)(a.code,{children:"/var/lib/docker/swarm/raft/"}),". Cada manager tiene un ID \xfanico y participa en el grupo Raft. El n\xfamero de managers debe ser impar (3, 5, 7) para maximizar tolerancia a fallos. El quorum es (N/2)+1. Con 3 managers, quorum=2, tolerancia=1 fallo. Con 5 managers, quorum=3, tolerancia=2. La elecci\xf3n de l\xedder t\xedpicamente toma <1 segundo."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-swarmkit-y-c\xf3mo-se-relaciona-con-docker-swarm-qu\xe9-otros-proyectos-usan-swarmkit",children:"2. [Investigar] \xbfQu\xe9 es SwarmKit y c\xf3mo se relaciona con Docker Swarm? \xbfQu\xe9 otros proyectos usan SwarmKit?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": SwarmKit (github.com/moby/swarmkit) es el toolkit open-source de orquestaci\xf3n que implementa el n\xfacleo de Docker Swarm: Raft consensus, scheduler, dispatcher, allocator, service management, networking, y secrets. Docker Swarm es esencialmente Docker Engine + SwarmKit integrado. SwarmKit fue separado del c\xf3digo de Docker en 2016-2017 como parte del proyecto Moby, para permitir que otros proyectos usaran el orquestador sin dependencia de Docker Engine. Proyectos que usan SwarmKit: ",(0,s.jsx)(a.strong,{children:"InfraKit"})," (Docker, toolkit para infraestructura declarativa), ",(0,s.jsx)(a.strong,{children:"Docker App"})," (experimental, Docker application format), y varios proyectos acad\xe9micos y de investigaci\xf3n."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Andrea Luzzardi y el equipo de Docker (antes de la venta a Mirantis) dise\xf1aron SwarmKit como un orquestador modular y reusable. La separaci\xf3n fue an\xe1loga a c\xf3mo containerd se separ\xf3: un componente core que puede integrarse en diferentes productos. SwarmKit implementa el scheduler (con estrategias spread/binpack), el dispatcher (env\xeda tareas a workers), y el allocator (asigna IPs, puertos). En Docker, SwarmKit se compila dentro de dockerd como un subsistema. La API de SwarmKit es gRPC, y el CLI de Docker traduce comandos a llamadas gRPC de SwarmKit internamente."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-c\xf3mo-funciona-exactamente-el-gossip-protocol-swim-en-swarm-y-qu\xe9-informaci\xf3n-se-comparte-por-qu\xe9-es-eventualmente-consistente-y-no-fuertemente-consistente-como-raft",children:'3. [Investigar] \xbfC\xf3mo funciona exactamente el gossip protocol (SWIM) en Swarm y qu\xe9 informaci\xf3n se comparte? \xbfPor qu\xe9 es "eventualmente consistente" y no "fuertemente consistente" como Raft?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Swarm usa SWIM (Scalable Weakly-consistent Infection-style Membership), un protocolo de gossip donde cada nodo peri\xf3dicamente selecciona un subconjunto aleatorio de otros nodos y les env\xeda un "ping" con su estado conocido. La informaci\xf3n compartida incluye: membres\xeda de nodos (qu\xe9 nodos existen), estado de nodos (alive, suspect, dead), IPs y puertos de otros nodos, y la tabla de encaminamiento de redes overlay (qu\xe9 IP corresponde a qu\xe9 nodo para VXLAN). El gossip es "eventualmente consistente" (no "fuertemente" como Raft) porque: 1) la informaci\xf3n se propaga nodo-a-nodo sin un l\xedder central (peer-to-peer), 2) no hay garant\xeda de que todos los nodos tengan el mismo estado en todo momento (puede haber desfases temporales), 3) eventualmente (en segundos), la informaci\xf3n converge. El estado del servicio (r\xe9plicas, updates) es fuertemente consistente (v\xeda Raft en los managers). El gossip es para descubrimiento de red y membres\xeda, que no requiere consistencia fuerte.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": El protocolo SWIM fue propuesto por Abhinandan Das et al. (ACM SIGCOMM 2002) y ha sido usado por Consul (HashiCorp), Serf (HashiCorp), y Cassandra. Swarm implementa SWIM sobre UDP/TCP puerto 7946. Cada nodo mantiene una tabla de miembros con: nombre, IP, estado, y timestamp del \xfaltimo heartbeat. El di\xe1metro de la red gossip es logar\xedtmico (O(log N) rounds para propagar informaci\xf3n a N nodos). Esto significa que Swarm escala bien a cientos de nodos sin sobrecarga de managers."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-c\xf3mo-se-compara-docker-swarm-con-hashicorp-nomad-como-orquestador-simple-en-qu\xe9-casos-nomad-es-preferible-a-swarm",children:"4. [Investigar] \xbfC\xf3mo se compara Docker Swarm con HashiCorp Nomad como orquestador simple? \xbfEn qu\xe9 casos Nomad es preferible a Swarm?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Ambos son orquestadores "simples" comparados con K8s, pero difieren en filosof\xeda: 1) ',(0,s.jsx)(a.strong,{children:"Scope"}),": Swarm orquesta solo contenedores Docker. Nomad orquesta cualquier workload (Docker, Podman, QEMU, Java, raw exec, Windows Containers). 2) ",(0,s.jsx)(a.strong,{children:"Arquitectura"}),": Swarm integra orquestaci\xf3n en Docker Engine (acoplado). Nomad es independiente (desacoplado) con su propio binario y agentes. 3) ",(0,s.jsx)(a.strong,{children:"Configuraci\xf3n"}),": Swarm usa Compose files para stacks. Nomad usa HCL (HashiCorp Configuration Language) para jobs. 4) ",(0,s.jsx)(a.strong,{children:"Ecosistema"}),": Swarm se integra con el ecosistema Docker (Compose, CLI, Hub). Nomad se integra con el ecosistema HashiCorp (Consul, Vault, Terraform). Nomad es preferible cuando: necesit\xe1s orquestar workloads que no son contenedores (batch jobs, VMs, raw exec), quer\xe9s integraci\xf3n nativa con Consul/Vault, o necesit\xe1s multi-regi\xf3n/multi-cloud scheduling (Nomad es multi-datacenter nativamente, Swarm es single-cluster)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': Nomad fue creado por Armon Dadgar (HashiCorp) con la filosof\xeda de "un scheduler, muchos tipos de workload". Es un solo binario (~80 MB) que funciona como server (manager) y client (worker). Nomad es popular en entornos que ya usan HashiCorp stack (Consul para service discovery, Vault para secrets). Para equipos que solo necesitan orquestar Docker, Swarm es m\xe1s simple (activado con ',(0,s.jsx)(a.code,{children:"docker swarm init"}),", sin binarios extra). Para equipos con workloads mixtos o multi-cloud, Nomad es m\xe1s flexible."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-el-puerto-2377-para-comunicaci\xf3n-manager-worker-qu\xe9-otros-puertos-usa-swarm-y-qu\xe9-protocolos-por-qu\xe9-la-seguridad-de-red-es-cr\xedtica-en-un-cluster-swarm",children:"5. [Conectar] La clase menciona el puerto 2377 para comunicaci\xf3n manager-worker. \xbfQu\xe9 otros puertos usa Swarm y qu\xe9 protocolos? \xbfPor qu\xe9 la seguridad de red es cr\xedtica en un cluster Swarm?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Puertos de Swarm: 1) 2377 TCP: comunicaci\xf3n de gesti\xf3n entre managers y workers (formato gRPC, protegido por TLS mutuo). 2) 7946 TCP/UDP: gossip network (membres\xeda, descubrimiento de nodos, estado de redes). 3) 4789 UDP: VXLAN data plane (tr\xe1fico de aplicaci\xf3n entre contenedores en redes overlay). Estos puertos deben estar abiertos entre TODOS los nodos del cluster (managers y workers). La seguridad de red es cr\xedtica porque: el tr\xe1fico de la red overlay (VXLAN) viaja SIN cifrar por defecto (aunque IPSEC puede habilitarse), el tr\xe1fico de gossip incluye informaci\xf3n sensible (IPs de todos los nodos, estado), y el puerto de gesti\xf3n (2377) debe estar protegido (TLS mutuo por defecto, pero si un atacante obtiene el token de join, puede a\xf1adir nodos maliciosos al cluster)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de Swarm (docs.docker.com/engine/swarm/networking) detalla estos puertos. Swarm habilita TLS mutuo autom\xe1ticamente (certificados generados durante ",(0,s.jsx)(a.code,{children:"init"})," y ",(0,s.jsx)(a.code,{children:"join"}),"). Pero la capa de red subyacente debe ser segura. En la pr\xe1ctica, Swarm se despliega en una red privada (VPC, VLAN) donde estos puertos est\xe1n abiertos entre nodos pero no expuestos a internet. El VXLAN sin cifrar (puerto 4789) es un vector: un atacante en la misma red que pueda sniffear paquetes VXLAN puede leer el tr\xe1fico entre contenedores. La mitigaci\xf3n: habilitar IPSEC en redes overlay (",(0,s.jsx)(a.code,{children:"docker network create --opt encrypted"}),")."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"6-conectar-c\xf3mo-funciona-exactamente-el-scheduler-de-swarmkit-y-qu\xe9-estrategias-de-placement-ofrece-c\xf3mo-se-relaciona-con-los-constraints-y-preferences-de-la-clase",children:"6. [Conectar] \xbfC\xf3mo funciona exactamente el scheduler de SwarmKit y qu\xe9 estrategias de placement ofrece? \xbfC\xf3mo se relaciona con los constraints y preferences de la clase?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": El scheduler de SwarmKit (componente dentro de Swarm) recibe tareas (tasks) del orchestrator y las asigna a nodos workers en dos fases: 1) ",(0,s.jsx)(a.strong,{children:"Filtrado (constraints)"})," \u2014 elimina nodos que no cumplen los requisitos: node availability (active, drain), constraints de labels (",(0,s.jsx)(a.code,{children:"node.labels.env==prod"}),"), recursos disponibles (CPU/memoria suficiente), puertos publicados (sin conflictos). 2) ",(0,s.jsx)(a.strong,{children:"Ranking (preferences)"})," \u2014 ordena los nodos restantes seg\xfan estrategias: ",(0,s.jsx)(a.strong,{children:"spread"})," (distribuir uniformemente, default), ",(0,s.jsx)(a.strong,{children:"binpack"})," (concentrar en el menor n\xfamero de nodos, para optimizar uso de recursos), ",(0,s.jsx)(a.strong,{children:"random"})," (introspectivo, para testing). Preferencias adicionales: ",(0,s.jsx)(a.code,{children:"--placement-pref spread=node.labels.az"})," distribuye entre availability zones. El scheduler selecciona el nodo con mayor ranking y le asigna la tarea (env\xedo via dispatcher)."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': El c\xf3digo de SwarmKit (github.com/moby/swarmkit) implementa el scheduler con un modelo de plugins. Las constraints son filtros booleanos (el nodo cumple o no). Las preferences son funciones de ranking que ordenan nodos. La combinaci\xf3n permite: "solo nodos con SSD y label env=prod, distribuyendo uniformemente entre AZs". Si ning\xfan nodo cumple los constraints, la tarea queda en estado ',(0,s.jsx)(a.code,{children:"Pending"})," con mensaje de error. El scheduler re-eval\xfaa peri\xf3dicamente (por si nuevos nodos se unen o cambian labels). Esto es conceptualmente similar al scheduler de K8s (kube-scheduler con predicates y priorities) pero m\xe1s simple."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"7-conectar-qu\xe9-es-el-raft-log-compactation-y-por-qu\xe9-es-cr\xedtico-para-la-salud-a-largo-plazo-de-un-cluster-swarm-qu\xe9-pasa-si-el-log-crece-sin-control",children:'7. [Conectar] \xbfQu\xe9 es el "Raft log compactation" y por qu\xe9 es cr\xedtico para la salud a largo plazo de un cluster Swarm? \xbfQu\xe9 pasa si el log crece sin control?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": El Raft log es una secuencia de entradas (creaci\xf3n de servicios, updates, secrets, configs) que crece con cada operaci\xf3n en el cluster. Si no se compacta: 1) consume espacio en disco indefinidamente en cada manager (el log es replicado), 2) al reiniciar un manager, debe reproducir el log COMPLETO para reconstruir el estado, haciendo que los reinicios sean cada vez m\xe1s lentos, 3) el snapshotting (compactaci\xf3n) reemplaza las entradas viejas del log con un snapshot del estado actual. SwarmKit autom\xe1ticamente hace snapshotting cuando el log supera un threshold configurable (por defecto, 10,000 entradas o 5 MB). Despu\xe9s del snapshot, las entradas viejas se eliminan."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n de Raft (Diego Ongaro) enfatiza que la compactaci\xf3n es esencial para la operaci\xf3n continua. Sin snapshotting, un cluster de producci\xf3n que crea/actualiza servicios diariamente podr\xeda acumular gigabytes de log en meses, haciendo los reinicios de managers prohibitivamente lentos (horas para reproducir). SwarmKit usa el snapshot system de la biblioteca etcd-io/raft. El snapshot se almacena en ",(0,s.jsx)(a.code,{children:"/var/lib/docker/swarm/raft/snap/"}),". Para clusters longevos, monitorear el tama\xf1o del log y forzar snapshotting peri\xf3dico (no hay comando directo, pero reiniciar un manager lo dispara) es una pr\xe1ctica de mantenimiento."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-docker-swarm-vs-kubernetes-para-startups-es-swarm-suficiente-o-es-una-decisi\xf3n-que-limita-el-crecimiento-futuro",children:"8. [Cuestionar] Docker Swarm vs Kubernetes para startups: \xbfEs Swarm suficiente o es una decisi\xf3n que limita el crecimiento futuro?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": Swarm es suficiente para startups en etapas tempranas que: 1) tienen <10 servicios, 2) corren en un solo cluster peque\xf1o (3-10 nodos), 3) usan principalmente Docker Compose, 4) no necesitan features avanzadas de K8s (operators, CRDs, service mesh, HPA). La ventaja: Swarm es radicalmente m\xe1s simple (se activa con un comando, usa el mismo CLI Docker, los devs no necesitan aprender kubectl ni YAML de K8s). La limitaci\xf3n: si la startup crece y necesita operadores de BD (CloudNativePG), CI/CD con GitOps (Flux/ArgoCD), service mesh (Istio), auto-scaling horizontal (HPA), o pol\xedticas de seguridad avanzadas (OPA/Gatekeeper), migrar de Swarm a K8s es un esfuerzo significativo (reescribir todos los manifiestos). La decisi\xf3n depende de ambici\xf3n de escala: si el plan es ser un unicornio, empezar con K8s (o al menos tener un plan de migraci\xf3n). Si el plan es un negocio rentable con crecimiento moderado, Swarm puede ser suficiente indefinidamente."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La comunidad debate esto frecuentemente en /r/docker, /r/kubernetes, y HackerNews. La postura pragm\xe1tica de empresas como 37signals (Basecamp, Hey) es que K8s es overkill para el 95% de las empresas. Ellos usan Docker + kamal (toolkit de deploy simple). Swarm est\xe1 en un punto intermedio: m\xe1s capaz que docker-compose standalone pero mucho m\xe1s simple que K8s. La realidad: Swarm est\xe1 en modo mantenimiento (Docker Inc. no invierte en nuevas features mayores para Swarm) mientras K8s tiene miles de contribuidores y ecosistema masivo. Para una startup, la pregunta es: \xbfquiero simplicidad operativa (Swarm) o ecosistema y future-proofing (K8s)?"]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"9-cuestionar-docker-swarm-est\xe1-muerto-evalu\xe1-su-estado-actual-2025-y-si-docker-inc-sigue-invirtiendo-en-\xe9l",children:"9. [Cuestionar] \xbfDocker Swarm est\xe1 muerto? Evalu\xe1 su estado actual (2025) y si Docker Inc. sigue invirtiendo en \xe9l."}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Swarm no est\xe1 muerto, pero est\xe1 en modo mantenimiento. Docker Inc. (post-venta del negocio enterprise a Mirantis, 2019) contin\xfaa manteniendo Swarm en Docker Engine (bug fixes, parches de seguridad, compatibilidad con nuevas versiones de kernel), pero NO est\xe1 desarrollando nuevas features significativas. La \xfaltima feature mayor fue SwarmKit con soporte CSI (Container Storage Interface) que lleg\xf3 en Docker 23.0. Docker Inc. enfoca su inversi\xf3n en: Docker Desktop, Docker Hub, Docker Scout, BuildKit, y Compose. Swarm sigue siendo usado (encuestas de la comunidad muestran ~15-20% de usuarios Docker usan Swarm mode), principalmente en peque\xf1as y medianas empresas, edge computing, y entornos donde la simplicidad es prioridad. No est\xe1 "muerto" (el c\xf3digo es mantenido), pero est\xe1 "terminado" en el sentido de que no evolucionar\xe1 significativamente.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": Despu\xe9s de vender Docker Enterprise a Mirantis (2019), Docker Inc. cambi\xf3 su foco de orquestaci\xf3n (Swarm vs K8s) a herramientas de desarrollo (Desktop, Hub, Build). Mirantis continu\xf3 desarrollando Swarm dentro de Mirantis Kubernetes Engine (MKE, antes Docker Enterprise), pero el Swarm open-source en Docker Engine qued\xf3 en mantenimiento. La comunidad (incluyendo ex-empleados de Docker como Andrea Luzzardi) ha expresado que Swarm cumpli\xf3 su prop\xf3sito: demostrar que la orquestaci\xf3n simple es posible, y la industria eligi\xf3 K8s como est\xe1ndar. Para nuevos proyectos, elegir Swarm es una decisi\xf3n que debe considerar la baja probabilidad de nuevas features."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-es-el-raft-consensus-de-swarm-un-cuello-de-botella-qu\xe9-implicaciones-de-rendimiento-tiene-que-todas-las-operaciones-de-escritura-pasen-por-el-l\xedder",children:"10. [Cuestionar] \xbfEs el Raft consensus de Swarm un cuello de botella? \xbfQu\xe9 implicaciones de rendimiento tiene que todas las operaciones de escritura pasen por el l\xedder?"}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": S\xed, el modelo de Raft tiene limitaciones de rendimiento: 1) todas las operaciones de escritura (crear servicios, updates, secrets) son serializadas a trav\xe9s del l\xedder, 2) el l\xedder debe replicar cada entrada a la mayor\xeda de followers antes de commitear, a\xf1adiendo latencia de red (RTT entre nodos), 3) el throughput de escritura est\xe1 limitado por el disco m\xe1s lento entre los managers (cada entrada se persiste en disco antes de replicarse). En la pr\xe1ctica, para la mayor\xeda de los casos de uso (crear/actualizar servicios es una operaci\xf3n infrecuente, comparado con el tr\xe1fico de aplicaci\xf3n que no pasa por Raft), esto NO es un cuello de botella. El cuello de botella real en Swarm es la red de datos (VXLAN, 4789/UDP), no el plano de control (Raft). Solo en cl\xfasteres extremadamente din\xe1micos (thousands de servicios creados/destruidos por minuto) Raft puede ser limitante."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La tesis de Ongaro analiza el rendimiento de Raft. El throughput es ~10,000+ operaciones/segundo en hardware moderno con SSD. Swarm t\xedpicamente ejecuta operaciones de gesti\xf3n en el orden de decenas por minuto (crear servicios, updates), no miles. La latencia de escritura es t\xedpicamente <10ms (RTT de red + fsync del l\xedder). Comparativamente, etcd en K8s tiene las mismas limitaciones de Raft (todas las escrituras a K8s pasan por etcd, que tambi\xe9n usa Raft). La diferencia es que K8s escala el plano de control con m\xfaltiples API servers (que leen de etcd) y caching. Swarm no tiene esta separaci\xf3n (el manager es API server + Raft node). Para el 99% de los deployments, el rendimiento de Raft no es un factor limitante."]})]})}function u(e={}){const{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>t});var r=o(96540);const s={},n=r.createContext(s);function i(e){const a=r.useContext(n);return r.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),r.createElement(n.Provider,{value:a},e.children)}}}]);